+  assert.match(workflow, /INSTAGRAM_APP_ID: \$\{\{ secrets\.INSTAGRAM_APP_ID \}\}/);
+  assert.doesNotMatch(workflow, /INSTAGRAM_APP_ID[^\n]*\|\|/);
+});

